Author: Neil Dhar <neildhar@meta.com>
Date:   Tue Jul 18 17:46:41 2023 -0700

    Fix max character handling in convertUTF16ToUTF8WithReplacements

    Summary:
    The current version incorrectly reports that strings with length (in
    code-points) equal to the input string are truncated.

    Reviewed By: avp

    Differential Revision: D47555184

    fbshipit-source-id: ca6f876b2f7fc52159a43aa63b85564b8d840795

diff --git a/lib/Support/UTF8.cpp b/lib/Support/UTF8.cpp
index 489a78f4d..bf27d2671 100644
--- a/lib/Support/UTF8.cpp
+++ b/lib/Support/UTF8.cpp
@@ -75,8 +75,8 @@ bool convertUTF16ToUTF8WithReplacements(
     // Condition checks are easier if this number is set to the max value.
     maxCharacters = std::numeric_limits<size_t>::max();
   }
-  for (auto cur = input.begin(), end = input.end();
-       cur < end && currNumCharacters < maxCharacters;
+  auto cur = input.begin(), end = input.end();
+  for (; cur < end && currNumCharacters < maxCharacters;
        ++cur, ++currNumCharacters) {
     char16_t c = cur[0];
     // ASCII fast-path.
@@ -109,7 +109,7 @@ bool convertUTF16ToUTF8WithReplacements(
     encodeUTF8(ptr, c32);
     out.insert(out.end(), buff, ptr);
   }
-  return currNumCharacters < maxCharacters;
+  return cur == end;
 }

 void convertUTF16ToUTF8WithSingleSurrogates(
diff --git a/unittests/Support/UnicodeTest.cpp b/unittests/Support/UnicodeTest.cpp
index 94d3bf813..0ca577793 100644
--- a/unittests/Support/UnicodeTest.cpp
+++ b/unittests/Support/UnicodeTest.cpp
@@ -107,6 +107,11 @@ TEST(StringTest, UTF16ToUTF8StringWithReplacements) {
   strAndFullyWritten = convertWithMaxChars({0xD83D, 0xDE39, 0xD83D, 0xDE39}, 1);
   EXPECT_EQ(bytes({0xF0, 0x9F, 0x98, 0xB9}), strAndFullyWritten.first);
   EXPECT_EQ(false, strAndFullyWritten.second);
+
+  // Check that strings equal to the max length are correctly reported.
+  strAndFullyWritten = convertWithMaxChars({'a', 'b', 'c'}, 3);
+  EXPECT_EQ(bytes({'a', 'b', 'c'}), strAndFullyWritten.first);
+  EXPECT_EQ(true, strAndFullyWritten.second);
 }

